//! Sleep score from stage counts ([`sleep_score`]) or from durations in minutes
//! ([`sleep_score_minutes`]), with age-dependent limits and a timing contributor.
//! See `docs/algorithms/metrics.md`; the vectors in the tests are generated by
//! `tools/gen_public_vectors_sleep.py`.
//!
//! Nine inputs are mapped to contributors in 0..100 by a piecewise-linear curve (shared Y
//! values 0, 25, 95, 100 and four X knots per input, integer arithmetic) and combined as
//! `round(sum(w_i * c_i) / 100)`. Rows 0..2 (total, deep, REM) have age-dependent knots from
//! the limits calculation, which uses float32 arithmetic with one fused multiply-add and
//! round-half-away conversions. The timing contributor uses float32 arithmetic with
//! fused multiply-adds.

/// Combiner weights, in input order.
pub const WEIGHTS: [i64; 9] = [35, 10, 10, 10, 10, 5, 5, 5, 10];
const Y: [i64; 4] = [0, 25, 95, 100];
/// Rows 3..8 are constants; rows 0..2 come from `limits_v2`.
const STATIC: [[i64; 4]; 6] = [
    [30, 60, 90, 95],
    [60, 28, 2, 0],
    [240, 128, 16, 0],
    [80, 50, 25, 15],
    [96, 48, 16, 0],
    [390, 240, 100, 90],
];

/// Round to nearest, ties away from zero.
fn round_away(x: f32) -> i64 {
    x.round() as i64
}

/// Knots of rows 0..2 (total, deep, REM) for an age in years.
pub fn limits_v2(age: u8) -> [[i64; 4]; 3] {
    let a = age as i64;
    let row_peak = 0x1E6 - ((a * 0x1C5) >> 8);
    let fit = (age as f32).mul_add(f32::from_bits(0xBF91_26E9), f32::from_bits(0x42E7_47AE));
    let m = (((round_away(fit) + 0x8000) & 0xFFFF) - 0x8000).max(20);
    let r = (0x72 - ((a * 0x155) >> 9)).max(60);
    let top = if age < 31 { (row_peak * 5 + 2) >> 2 } else { 0x21C };
    [
        [0, (row_peak + 1) >> 1, (row_peak * 0x12E + 0x80) >> 8, top],
        [0, round_away(m as f32 / 4.0), m, round_away(m as f32 * 1.25)],
        [0, round_away(r as f32 / 4.0), r, round_away(r as f32 * 1.25)],
    ]
}

/// Integer division: truncates toward zero; division by zero gives 0.
fn div_trunc(a: i64, b: i64) -> i64 {
    if b == 0 {
        0
    } else {
        a / b
    }
}

/// Contributor value (0..100) for input `v` on knots `k`: round half up for ascending X,
/// half down for descending X.
pub fn curve(v: i64, k: &[i64; 4]) -> i64 {
    let i = if k[1] > k[0] {
        if v <= k[0] {
            return 0;
        }
        if v <= k[1] {
            1
        } else if v > k[2] {
            3
        } else {
            2
        }
    } else {
        if v >= k[0] {
            return 0;
        }
        if v >= k[1] {
            1
        } else if v < k[2] {
            3
        } else {
            2
        }
    };
    let (lo, hi) = (k[i - 1], k[i]);
    let d = hi - lo;
    if d == 0 {
        return 0;
    }
    let mut n = (v - lo) * (Y[i] - Y[i - 1]);
    n += if d > 0 { d >> 1 } else { ((-d) & 0xFFFE) >> 1 };
    (div_trunc(n, d) + Y[i - 1]).clamp(0, 100)
}

/// Float32 score in 0..100. A `day` of 1..6
/// selects the narrow windows; other values use a reference of 180 and wider windows.
pub fn timing_score(day: u8, reference: f32, x: f32) -> f32 {
    let inside = (1..=6).contains(&day);
    let a: f32 = if inside { -30.0 } else { -45.0 };
    let p: f32 = if inside { reference } else { 180.0 };
    let q: f32 = if inside { 30.0 } else { 45.0 };
    let t = a + -150.0;
    let b1 = p + t;
    let b0 = p + (t + -130.0);

    let interp = |lo: f32, hi: f32, ylo: f32, yhi: f32| -> f32 {
        if hi == lo {
            return 0.0;
        }
        let slope = (yhi - ylo) / (hi - lo);
        (x - lo).mul_add(slope, ylo).max(0.0).min(100.0)
    };

    if b1 >= x && b0 <= x {
        return interp(b0, b1, 0.0, 25.0);
    }
    let b2 = p + a;
    if b2 >= x && b1 <= x {
        return interp(b1, b2, 25.0, 100.0);
    }
    let b3 = p + q;
    if !(b2 > x || b3 < x) {
        return interp(b2, b3, 100.0, 100.0);
    }
    let ext = q + 150.0;
    let b4 = p + ext;
    if !(b3 > x || b4 < x) {
        return interp(b3, b4, 100.0, 25.0);
    }
    if b4 > x {
        return 0.0;
    }
    let b5 = p + (ext + 130.0);
    if b5 >= x {
        return interp(b4, b5, 25.0, 0.0);
    }
    0.0
}

/// Timing arguments: `day` 0xFF disables the timing function (the midpoint curve is used),
/// `reference` is the int32 passed to it, and `mid` the signed 16-bit midpoint.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Timing {
    pub mid: i16,
    pub day: u8,
    pub reference: i32,
}

/// Inner combiner. `inputs` are the nine u16 values (see `docs/algorithms/metrics.md`).
/// Returns the nine per-input contributors (restless rows already
/// scaled by `(2c + 3) / 6`) and the total.
pub fn score_from_inputs(inputs: &[i64; 9], age: u8, timing: Timing) -> ([i64; 9], i64) {
    let l = limits_v2(age);
    let rows = [
        l[0], l[1], l[2], STATIC[0], STATIC[1], STATIC[2], STATIC[3], STATIC[4], STATIC[5],
    ];
    let mut acc = 0i64;
    let mut out = [0i64; 9];
    for i in 0..9 {
        let v = inputs[i] & 0xFFFF;
        let mut c = if i == 8 && timing.day != 0xFF {
            round_away(timing_score(
                timing.day,
                timing.reference as f32,
                timing.mid as f32,
            ))
        } else {
            curve(v, &rows[i])
        };
        acc += c * WEIGHTS[i];
        c = c.clamp(0, 100);
        if (5..=7).contains(&i) {
            c = (((2 * c + 3) & 0xFF) * 171) >> 10;
        }
        out[i] = c;
    }
    let total = if acc + 50 < (1 << 32) {
        ((acc + 50) * 0x51EB_851F) >> 37
    } else {
        (acc + 50) / 100
    };
    (out, total)
}

fn fix(c: i64) -> u32 {
    (if c == 0 {
        1
    } else if c >= 101 {
        100
    } else {
        c
    }) as u32
}

/// The seven contributors: total, deep, REM, efficiency, latency, restfulness
/// (sum of rows 5..7) and timing.
fn contributors(o: &[i64; 9]) -> [u32; 7] {
    [
        fix(o[0]),
        fix(o[1]),
        fix(o[2]),
        fix(o[3]),
        fix(o[4]),
        fix(o[5] + o[6] + o[7]),
        fix(o[8]),
    ]
}

fn div_unsigned(a: i64, b: i64) -> i64 {
    if b == 0 {
        0
    } else {
        a / b
    }
}

/// Inputs of [`sleep_score`]. Stages and `time_in_bed` are in 30-second epochs.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Sleep {
    pub age: u8,
    pub time_in_bed: u16,
    pub deep: u16,
    pub light: u16,
    pub rem: u16,
    /// Latency in epochs.
    pub latency: u8,
    pub restless: u8,
    pub tosses: u16,
    pub ext: u8,
}

/// Sleep score from stage counts: (7 contributors, total score).
pub fn sleep_score(s: &Sleep, timing: Timing) -> ([u32; 7], u32) {
    let (a, b, c, d) = (
        s.time_in_bed as i64,
        s.deep as i64,
        s.light as i64,
        s.rem as i64,
    );
    let b_plus = b + 1;
    let t = ((b_plus + c + d) >> 1) & 0xFFFF;
    let denom = t.max(0x3C);
    let h = denom >> 1;
    let e = ((s.latency as i64) + 1) >> 1;
    let inputs = [
        t,
        (b_plus >> 1) & 0xFFFF,
        ((d + 1) >> 1) & 0xFFFF,
        div_unsigned(t * 100 + (a >> 2), a >> 1) & 0xFFFF,
        (e - 15).abs(),
        div_unsigned(s.restless as i64 * 0x1A40 + h, denom) & 0xFFFF,
        div_unsigned(s.tosses as i64 * 50 + h, denom) & 0xFFFF,
        div_unsigned(s.ext as i64 * 0x1A40 + h, denom) & 0xFFFF,
        (timing.mid as i64 - 90).abs(),
    ];
    let (out, total) = score_from_inputs(&inputs, s.age, timing);
    (contributors(&out), total as u32)
}

/// Inputs of [`sleep_score_minutes`]: durations in minutes, `efficiency` in
/// percent, `latency` used as is.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct SleepMinutes {
    pub age: u8,
    pub total: u16,
    pub deep: u16,
    pub rem: u16,
    pub efficiency: u8,
    pub latency: u8,
    pub restless: u8,
    pub tosses: u16,
    pub ext: u8,
}

/// Sleep score from durations in minutes: (7 contributors, total score).
pub fn sleep_score_minutes(s: &SleepMinutes, timing: Timing) -> ([u32; 7], u32) {
    let a = s.total as i64;
    let inputs = [
        a,
        s.deep as i64,
        s.rem as i64,
        s.efficiency as i64,
        s.latency as i64,
        s.restless as i64,
        div_unsigned(s.tosses as i64 * 50 + (a >> 1), a) & 0xFFFF,
        s.ext as i64,
        (timing.mid as i64 - 90).abs(),
    ];
    let (out, total) = score_from_inputs(&inputs, s.age, timing);
    (contributors(&out), total as u32)
}

#[cfg(test)]
mod tests {
    use super::*;
    fn timing(v: &[i64; 12]) -> Timing {
        Timing {
            mid: v[9] as i16,
            day: v[10] as u8,
            reference: v[11] as i32,
        }
    }

    macro_rules! vector_tests {
        () => {
        #[test]
        fn timing_matches_reference() {
            for (i, &(day, reference, x, bits)) in TIMING.iter().enumerate() {
                let got = timing_score(day, reference as f32, x as f32);
                assert_eq!(
                    got.to_bits(),
                    bits,
                    "case {i}: {got} vs {}",
                    f32::from_bits(bits)
                );
            }
        }

        #[test]
        fn calculate_matches_reference() {
            for (i, (v, want, want_total)) in CALCULATE.iter().enumerate() {
                let s = Sleep {
                    age: v[0] as u8,
                    time_in_bed: v[1] as u16,
                    deep: v[2] as u16,
                    light: v[3] as u16,
                    rem: v[4] as u16,
                    latency: v[5] as u8,
                    restless: v[6] as u8,
                    tosses: v[7] as u16,
                    ext: v[8] as u8,
                };
                assert_eq!(sleep_score(&s, timing(v)), (*want, *want_total), "case {i}");
            }
        }

        #[test]
        fn calculate_minutes_matches_reference() {
            for (i, (v, want, want_total)) in MINUTES.iter().enumerate() {
                let s = SleepMinutes {
                    age: v[0] as u8,
                    total: v[1] as u16,
                    deep: v[2] as u16,
                    rem: v[3] as u16,
                    efficiency: v[4] as u8,
                    latency: v[5] as u8,
                    restless: v[6] as u8,
                    tosses: v[7] as u16,
                    ext: v[8] as u8,
                };
                assert_eq!(
                    sleep_score_minutes(&s, timing(v)),
                    (*want, *want_total),
                    "case {i}"
                );
            }
        }
        };
    }

    #[test]
    fn age_limits_are_ordered_knots() {
        for age in 0..=255u8 {
            for (row, k) in limits_v2(age).iter().enumerate() {
                assert_eq!(k[0], 0, "age {age} row {row}");
                assert!(k[0] <= k[1] && k[1] <= k[2] && k[2] <= k[3], "age {age} row {row}: {k:?}");
            }
        }
    }

    mod python_port {
        use super::*;
        include!("vectors/sleep_score.rs");
        vector_tests!();
    }

}
